<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/auth_check.php';require_once dirname(__DIR__).'/bootstrap.php';require_once APP_ROOT.'/fpdf186/fpdf.php';
$febId=(int)($_GET['feb_id']??0);$type=($_GET['type']??'')==='bci'?'bci':'authorization';
$sql="SELECT feb.numero_feb,feb.montant_demande,feb.document_uid,bc.numero_bc client_order,c.nom_client,d.numero_devis,ipo.order_number,ipo.delivery_date,ipo.document_uid order_uid,da.authorization_number,da.planned_date,da.status,da.document_uid authorization_uid,s.name supplier_name,s.address supplier_address,s.phone supplier_phone,s.email supplier_email,CONCAT_WS(' ',u.prenom,u.nom) approver_name,da.approved_at,da.approver_signature FROM fiches_expression_besoin feb JOIN bons_commande bc ON bc.id=feb.bon_commande_id JOIN devis d ON d.id=bc.devis_id LEFT JOIN client c ON c.id_client=bc.client_id JOIN internal_purchase_orders ipo ON ipo.feb_id=feb.id JOIN disbursement_authorizations da ON da.feb_id=feb.id JOIN suppliers s ON s.id=ipo.supplier_id LEFT JOIN user_devis u ON u.id=da.approved_by WHERE feb.id=:id";$s=app_database()->prepare($sql);$s->execute(['id'=>$febId]);$d=$s->fetch();if(!$d){http_response_code(404);exit('Document achat introuvable.');}
$pdf=new class('P','mm','A4') extends FPDF{public array $d=[];public string $type='';private function t($v){return @iconv('UTF-8','windows-1252//TRANSLIT//IGNORE',(string)$v)?:$v;}function Header(){$logo=APP_ROOT.'/img/logo_fidest.png';if(is_file($logo))$this->Image($logo,14,8,30);$this->SetXY(50,8);$this->SetFont('Arial','B',12);$this->SetTextColor(34,37,75);$this->Cell(100,10,$this->t($this->type==='bci'?'BON DE COMMANDE INTERNE':'FICHE DE DÉCAISSEMENT'),1,0,'C');$uid=$this->type==='bci'?$this->d['order_uid']:$this->d['authorization_uid'];$this->SetXY(150,8);$this->SetFont('Arial','',6.5);$this->MultiCell(46,5,$this->t("ID : $uid\nVersion : 1\nISO 9001 · Document maîtrisé"),1);$this->SetDrawColor(250,189,2);$this->SetLineWidth(.8);$this->Line(14,31,196,31);}function Footer(){$this->SetY(-17);$this->SetFont('Arial','',6);$this->MultiCell(0,3,$this->t(app_branding()->footerBlock()),0,'C');}function row($a,$b){$this->SetFont('Arial','B',8);$this->SetFillColor(245,246,249);$this->Cell(47,8,$this->t($a),1,0,'L',true);$this->SetFont('Arial','',8);$this->Cell(135,8,$this->t($b?:'—'),1,1);}function render(){extract($this->d);$this->SetY(38);$this->SetFont('Arial','B',15);$this->Cell(0,10,$this->t($this->type==='bci'?$order_number:$authorization_number),0,1);$this->row('FEB',$numero_feb);$this->row('Commande client',$clientAPL = $client_order.' · '.$nom_client);$this->row('Devis',$numero_devis);$this->row($this->type==='bci'?'Fournisseur destinataire':'Bénéficiaire',$supplier_name);$this->row('Coordonnées',trim($supplier_address.' · '.$supplier_phone.' · '.$supplier_email,' ·'));$this->row($this->type==='bci'?'Livraison / exécution':'Date planifiée',$this->type==='bci'?$delivery_date:$planned_date);$this->row('Montant',number_format((float)$montant_demande,0,',',' ').' FCFA');$this->Ln(7);$this->SetFont('Arial','B',9);$this->SetFillColor(34,37,75);$this->SetTextColor(255);$this->Cell(182,8,$this->t($this->type==='bci'?'OBJET DE LA COMMANDE':'PORTÉE DE L’AUTORISATION'),0,1,'L',true);$this->SetTextColor(30);$this->SetFont('Arial','',9);$text=$this->type==='bci'?'Commande interne émise au fournisseur pour couvrir les besoins détaillés et approuvés dans la FEB '.$numero_feb.'.':'Cette fiche constitue le seul document autorisant le décaissement relatif à la FEB '.$numero_feb.'. Son exécution reste soumise à sa planification, à l’arrêté du point du jour et au visa requis.';$this->MultiCell(182,7,$this->t($text),1);$this->Ln(8);$this->SetFont('Arial','B',8);$this->Cell(90,25,$this->t('Validé et signé par\n'.$approver_name.'\n'.date('d/m/Y H:i',strtotime($approved_at))),1,0,'C');$this->Cell(92,25,$this->t($this->type==='bci'?'Bon adressé à : '.$supplier_name:'Statut : '.$status),1,0,'C');if($approver_signature&&is_file(APP_ROOT.'/'.$approver_signature)){try{$this->Image(APP_ROOT.'/'.$approver_signature,46,$this->GetY()+10,22,10);}catch(Throwable){}}}};
$pdf->d=$d;$pdf->type=$type;$pdf->AliasNbPages();$pdf->AddPage();$pdf->render();$number=$type==='bci'?$d['order_number']:$d['authorization_number'];header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.$number.'.pdf"');echo $pdf->Output('S');
